files.content:
* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  font-family: 'Courier New', monospace;
  background-color: #2d2d44;
  background-image:
    linear-gradient(45deg, #3a3a5c 25%, transparent 25%),
    linear-gradient(-45deg, #3a3a5c 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #3a3a5c 75%),
    linear-gradient(-45deg, transparent 75%, #3a3a5c 75%);
  background-size: 24px 24px;
  background-position: 0 0, 0 12px, 12px -12px, -12px 0;
}

.converter {
  width: min(92vw, 440px);
  padding: 24px;
  background: #e0e0e0;
  border: 6px solid #1a1a2e;
  box-shadow: 10px 10px 0 #0f0f1f;
}

h1 {
  margin: 0 0 16px;
  font-size: 1.5rem;
  text-align: center;
  text-transform: uppercase;
}

form {
  display: grid;
  gap: 12px;
}

label {
  font-weight: bold;
  margin-top: 6px;
}

input,
select,
button {
  width: 100%;
  padding: 10px;
  font: inherit;
  color: #1a1a2e;
  background: #fff;
  border: 4px solid #1a1a2e;
  border-radius: 0;
}

input:focus-visible,
select:focus-visible,
button:focus-visible {
  outline: 4px dashed #ffcc00;
  outline-offset: 2px;
}

button {
  font-weight: bold;
  text-transform: uppercase;
  background: #ff6b6b;
  cursor: pointer;
}

button:hover {
  background: #ff8e8e;
}

output {
  display: block;
  padding: 12px;
  font-size: 1.8rem;
  text-align: center;
  background: #1a1a2e;
  color: #7ef9ff;
  border: 4px solid #000;
}

output.error {
  color: #ff4d4d;
}

.formula {
  margin: 14px 0 0;
  padding: 8px;
  font-size: 0.9rem;
  background: #fff;
  border: 2px dashed #1a1a2e;
}

const form = document.getElementById('temp-form');
const temperature = document.getElementById('temperature');
const direction = document.getElementById('direction');
const result = document.getElementById('result');
const formula = document.getElementById('formula');

const converters = {
  'c-to-f': {
    text: 'Formula: °F = °C × 9/5 + 32',
    convert: (x) => x * 9 / 5 + 32
  },
  'f-to-c': {
    text: 'Formula: °C = (°F - 32) × 5/9',
    convert: (x) => (x - 32) * 5 / 9
  }
};

function updateFormula() {
  formula.textContent = converters[direction.value].text;
}

direction.addEventListener('change', updateFormula);
updateFormula();

form.addEventListener('submit', (event) => {
  event.preventDefault();
  const raw = temperature.value.trim();

  if (raw === '' || !Number.isFinite(Number(raw))) {
    result.textContent = 'Error';
    result.classList.add('error');
    return;
  }

  const value = Number(raw);
  const converted = converters[direction.value].convert(value);

  if (!Number.isFinite(converted)) {
    result.textContent = 'Error';
    result.classList.add('error');
    return;
  }

  result.textContent = converted.toFixed(2);
  result.classList.remove('error');
});
